import re,glob,json,sys
def norm(s): return re.sub(r'\s+',' ',s.replace('\u2019',"'").replace('\xa0',' ').replace('\u202f',' ').replace('\u2011','-').replace('\ufb01','fi').replace('\ufb02','fl')).strip()
docs={}
for f in glob.glob('corpus/*/*.txt'):
    c=f.split('/')[1]; t=open(f,encoding='utf-8',errors='replace').read()
    url=t.split('\n',1)[0][5:].strip(); body=re.sub(r'\s+',' ',t.split('\n',1)[1] if '\n' in t else '')
    docs.setdefault(c,[]).append((url,body))
